CARDIO.register({"item":"p203","meta":{"num":"p203","label":"203","spe":"pneumo","short":"Dyspnée aiguë/chronique","title":"Dyspnée aiguë et chronique","section":"P","chapter":7,"pages":"103-112","sdd":[]},"objectives":[{"id":"p203-obj-01","rank":"A","rubric":"Définition","title":"Connaître la définition de la dyspnée en général et plus particulièrement la dyspnée inspiratoire / expiratoire","desc":""},{"id":"p203-obj-02","rank":"A","rubric":"Diagnostic positif","title":"Dyspnée aiguë : connaître les éléments d'orientation étiologiques","desc":""},{"id":"p203-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Connaître l'examen clinique d'un patient présentant une dyspnée","desc":""},{"id":"p203-obj-04","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes de gravité accompagnant la dyspnée aiguë","desc":""},{"id":"p203-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Connaître les éléments d'orientation diagnostique face à une dyspnée chronique","desc":""},{"id":"p203-obj-06","rank":"A","rubric":"Étiologies","title":"Connaître les principales étiologies d'une dyspnée aiguë et leurs signes cliniques","desc":""},{"id":"p203-obj-07","rank":"A","rubric":"Étiologies","title":"Connaître les signes d'orientation étiologique","desc":""},{"id":"p203-obj-08","rank":"B","rubric":"Étiologies","title":"Connaître les étiologies plus rares d'une dyspnée aiguë","desc":""},{"id":"p203-obj-09","rank":"A","rubric":"Étiologies","title":"Connaître les principales étiologies cardiaques et pulmonaires d'une dyspnée chronique","desc":""},{"id":"p203-obj-10","rank":"A","rubric":"Pronostic","title":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","desc":""},{"id":"p203-obj-11","rank":"A","rubric":"Examens complémentaires","title":"Connaître les examens complémentaires de première intention en fonction du caractère aigu ou chronique","desc":""},{"id":"p203-obj-12","rank":"A","rubric":"Examens complémentaires","title":"Connaître les examens complémentaires de seconde intention en fonction du caractère aigu ou chronique","desc":""},{"id":"p203-obj-13","rank":"A","rubric":"Prise en charge","title":"Connaître les indications des examens radiologiques devant une dyspnée aiguë et chronique","desc":""},{"id":"p203-obj-14","rank":"A","rubric":"Examens complémentaires","title":"Connaître la stratégie d'exploration en imagerie devant une dyspnée aiguë de l'enfant","desc":""},{"id":"p203-obj-15","rank":"B","rubric":"Examens complémentaires","title":"Connaître les signes indirects sur une radiographie d'un corps étranger bronchique","desc":""},{"id":"p203-obj-16","rank":"A","rubric":"Contenu multimédia","title":"Radiographie de face dans un contexte de corps étranger","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p203-qroc-001","type":"QROC","rank":"A","objective":"p203-obj-01","tags":["définition"],"difficulty":1,"question":"Comment définit-on la dyspnée ?","answer":"Une perception de respiration inconfortable ou pénible","accept":["respiration inconfortable","respiration penible","inconfortable ou penible","difficulte a respirer","gene respiratoire"],"keywords":["inconfort","penib"],"explanation":"La dyspnée est une sensation ressentie au repos ou à l'exercice dans des situations qui n'entraînent habituellement aucune gêne ; elle ne se résume pas à une modification du rythme respiratoire.","src":"p. 105"},{"id":"p203-qroc-002","type":"QROC","rank":"A","objective":"p203-obj-01","tags":["définition","physiopathologie"],"difficulty":2,"question":"Quelles sont les deux composantes de la sensation de dyspnée, comme pour la douleur ?","answer":"Une composante sensorielle et une composante affective (émotionnelle)","accept":["sensorielle et affective","sensorielle et emotionnelle","sensorielle affective","sensorielle emotionnelle","composante sensorielle et une composante affective","composante sensorielle et une composante emotionnelle"],"keywords":["sensoriel","affectiv"],"explanation":"La composante sensorielle se perçoit comme une oppression thoracique ou une inspiration incomplète ; la composante affective comme un désagrément, une anxiété ou une frayeur.","src":"p. 105"},{"id":"p203-qroc-003","type":"QROC","rank":"A","objective":"p203-obj-01","tags":["définition"],"difficulty":1,"question":"Comment nomme-t-on l'augmentation excessive de la fréquence respiratoire ?","answer":"La tachypnée (ou polypnée)","accept":["tachypnee","polypnee"],"keywords":["tachypn"],"explanation":"On peut être tachypnéique sans être dyspnéique, ou dyspnéique sans être tachypnéique : la dyspnée est une sensation, pas un simple changement de rythme. La bradypnée est la réduction franche de la fréquence.","src":"p. 105, 107"},{"id":"p203-qroc-004","type":"QROC","rank":"A","objective":"p203-obj-01","tags":["définition"],"difficulty":1,"question":"Comment nomme-t-on l'augmentation de l'amplitude du volume courant ?","answer":"L'hyperpnée","accept":["hyperpnee","l hyperpnee"],"keywords":["hyperpn"],"explanation":"Son contraire, la diminution de l'amplitude du volume courant, est l'hypopnée.","src":"p. 107"},{"id":"p203-qroc-005","type":"QROC","rank":"A","objective":"p203-obj-01","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quelle atteinte évoque une dyspnée inspiratoire avec cornage ?","answer":"Une atteinte des voies aériennes supérieures (larynx, trachée extra-thoracique)","accept":["voies aeriennes superieures","larynx","trachee extra thoracique","obstruction des voies aeriennes superieures","atteinte des vas"],"keywords":["superieur"],"explanation":"Devant des bruits inspiratoires (stridor, cornage), on recherche systématiquement une atteinte ou une obstruction des voies aériennes supérieures.","src":"p. 104, 107"},{"id":"p203-qroc-006","type":"QROC","rank":"A","objective":"p203-obj-01","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quelle atteinte évoque une dyspnée avec sibilants expiratoires ?","answer":"Une pathologie des bronches","accept":["bronches","pathologie bronchique","atteinte bronchique","bronchique"],"keywords":["bronch"],"explanation":"Sibilants et sifflements sont des bruits expiratoires ; devant une dyspnée sifflante, on pense avant tout à l'asthme.","src":"p. 104, 107"},{"id":"p203-qroc-007","type":"QROC","rank":"A","objective":"p203-obj-02","tags":["diagnostic"],"difficulty":1,"question":"Quelle est la première des six questions clés à se poser devant une dyspnée ?","answer":"Est-elle aiguë ou chronique ?","accept":["aigue ou chronique","aigue chronique","dyspnee aigue ou chronique"],"keywords":["aigu","chroni"],"explanation":"Les questions suivantes portent sur le terrain, les facteurs favorisants, la rythmicité, les circonstances de survenue, les signes respiratoires associés et les signes extra-respiratoires.","src":"p. 104"},{"id":"p203-qroc-008","type":"QROC","rank":"A","objective":"p203-obj-02","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quel est le mode d'installation d'une dyspnée aiguë ?","answer":"Brutal, en quelques heures à quelques jours","accept":["brutal","brutale","installation brutale","quelques heures a quelques jours"],"keywords":["brutal"],"explanation":"On peut dater le début des symptômes ; la dyspnée chronique, elle, persiste depuis plusieurs semaines à plusieurs mois ou années, avec un début souvent progressif.","src":"p. 106"},{"id":"p203-qroc-009","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["définition","diagnostic"],"difficulty":1,"question":"À partir de quelle durée une dyspnée est-elle dite chronique ?","answer":"Au moins 8 semaines","accept":["8 semaines","2 mois","huit semaines"],"keywords":["8 sem"],"explanation":"Elle persiste depuis plusieurs semaines (8 ou plus) à plusieurs mois ou années ; il faut toujours chercher un facteur déclenchant ou une date de début, et préciser si elle s'est aggravée récemment.","src":"p. 106-107"},{"id":"p203-qroc-010","type":"QROC","rank":"A","objective":"p203-obj-06","tags":["étiologie","clinique"],"difficulty":1,"question":"Quelle est la première hypothèse devant une orthopnée ?","answer":"L'insuffisance cardiaque","accept":["insuffisance cardiaque","ic gauche","insuffisance cardiaque gauche"],"keywords":["cardiaque"],"explanation":"Une atteinte diaphragmatique reste possible ; l'orthopnée évoque aussi une obésité.","src":"p. 104, 107"},{"id":"p203-qroc-011","type":"QROC","rank":"A","objective":"p203-obj-06","tags":["étiologie","clinique"],"difficulty":1,"question":"Devant une dyspnée sifflante, quel diagnostic évoque-t-on avant tout ?","answer":"L'asthme","accept":["asthme","un asthme"],"keywords":["asthme"],"explanation":"Chez le sujet âgé, on pense aussi à la BPCO et à une cause cardiaque gauche (« pseudo-asthme cardiaque »).","src":"p. 104"},{"id":"p203-qroc-012","type":"QROC","rank":"A","objective":"p203-obj-06","tags":["étiologie","clinique"],"difficulty":2,"question":"Comment nomme-t-on le tableau de dyspnée sifflante d'origine cardiaque gauche chez le sujet âgé ?","answer":"Le pseudo-asthme cardiaque","accept":["pseudo asthme cardiaque","asthme cardiaque"],"keywords":["asthme cardiaque"],"explanation":"Une dyspnée sifflante du sujet âgé n'est pas toujours un asthme ou une BPCO : le cœur gauche peut être en cause.","src":"p. 104"},{"id":"p203-qroc-013","type":"QROC","rank":"A","objective":"p203-obj-06","tags":["étiologie","clinique"],"difficulty":1,"question":"Quels sont les deux diagnostics évoqués avant tout devant une dyspnée nocturne ?","answer":"L'œdème aigu pulmonaire et l'asthme","accept":["oap et asthme","asthme et oap","oap asthme","asthme oap","oedeme aigu pulmonaire et asthme","asthme et oedeme aigu pulmonaire"],"keywords":["asthme","oedeme"],"explanation":"La dyspnée peut être diurne, nocturne ou sans horaire particulier, avec ou sans périodicité liée à des facteurs favorisants ; l'horaire nocturne oriente d'emblée vers ces deux diagnostics.","src":"p. 107"},{"id":"p203-qroc-014","type":"QROC","rank":"A","objective":"p203-obj-10","tags":["urgence"],"difficulty":1,"question":"Quelle est la règle de principe devant toute dyspnée aiguë ?","answer":"Une urgence jusqu'à preuve du contraire : apprécier le pronostic vital","accept":["urgence","urgence jusqu a preuve du contraire","apprecier le pronostic vital","pronostic vital"],"keywords":["urgence"],"explanation":"Devant une dyspnée aiguë, il faut d'emblée apprécier le pronostic vital.","src":"p. 104"},{"id":"p203-qroc-015","type":"QROC","rank":"A","objective":"p203-obj-07","tags":["clinique","définition"],"difficulty":1,"question":"Comment nomme-t-on la dyspnée survenant en décubitus dorsal ?","answer":"L'orthopnée","accept":["orthopnee","l orthopnee"],"keywords":["orthopn"],"explanation":"Elle évoque une insuffisance cardiaque, une dysfonction diaphragmatique ou une obésité.","src":"p. 107"},{"id":"p203-qroc-016","type":"QROC","rank":"A","objective":"p203-obj-07","tags":["clinique","définition"],"difficulty":2,"question":"Comment nomme-t-on la dyspnée survenant en position penchée en avant ?","answer":"L'antépnée","accept":["antepnee","l antepnee"],"keywords":["antepn"],"explanation":"L'antépnée (dyspnée en antéflexion) évoque une dysfonction diaphragmatique ou une obésité.","src":"p. 107"},{"id":"p203-qroc-017","type":"QROC","rank":"A","objective":"p203-obj-07","tags":["clinique","définition"],"difficulty":2,"question":"Comment nomme-t-on la dyspnée survenant en position debout ?","answer":"La platypnée","accept":["platypnee","la platypnee"],"keywords":["platypn"],"explanation":"Elle évoque un shunt anatomique intracardiaque ou intrapulmonaire.","src":"p. 107"},{"id":"p203-qroc-018","type":"QROC","rank":"A","objective":"p203-obj-07","tags":["étiologie","clinique"],"difficulty":2,"question":"Quelles sont les trois étiologies à évoquer devant une orthopnée ?","answer":"Insuffisance cardiaque, dysfonction diaphragmatique, obésité","accept":["insuffisance cardiaque dysfonction diaphragmatique obesite","insuffisance cardiaque obesite dysfonction diaphragmatique","dysfonction diaphragmatique insuffisance cardiaque obesite"],"keywords":["cardiaque","diaphragm","obes"],"explanation":"L'antépnée évoque la dysfonction diaphragmatique ou l'obésité ; la platypnée, un shunt.","src":"p. 107"},{"id":"p203-qroc-019","type":"QROC","rank":"A","objective":"p203-obj-07","tags":["étiologie"],"difficulty":2,"question":"Quelle étiologie évoque une platypnée ?","answer":"Un shunt (foramen ovale perméable, fistule artério-veineuse...)","accept":["shunt","foramen ovale permeable","shunt intracardiaque","shunt intrapulmonaire"],"keywords":["shunt"],"explanation":"Les shunts en cause sont intracardiaques (foramen ovale perméable) ou intrapulmonaires, par exemple une malformation, une fistule artério-veineuse ou un syndrome hépato-pulmonaire.","src":"p. 107"},{"id":"p203-qroc-020","type":"QROC","rank":"B","objective":"p203-obj-08","tags":["diagnostic","étiologie"],"difficulty":1,"question":"Quel syndrome faut-il évoquer devant une dyspnée inexpliquée ?","answer":"Un syndrome d'hyperventilation (dysfunctional breathing)","accept":["hyperventilation","syndrome d hyperventilation","dysfunctional breathing"],"keywords":["hyperventil"],"explanation":"L'hyperventilation excessive est une réponse ventilatoire supérieure aux besoins physiologiques ; le dysfunctional breathing est un désordre du contrôle de la ventilation.","src":"p. 104, 107"},{"id":"p203-qroc-021","type":"QROC","rank":"B","objective":"p203-obj-08","tags":["physiopathologie","définition"],"difficulty":2,"question":"Comment nomme-t-on l'hyperventilation excessive où la fréquence respiratoire et le volume courant augmentent de façon non harmonieuse ?","answer":"Le dysfunctional breathing","accept":["dysfunctional breathing","dysfunctional"],"keywords":["dysfunctional"],"explanation":"Dans l'hyperventilation excessive au sens strict, la hausse de la fréquence et du volume courant est concomitante et harmonieuse ; le dysfunctional breathing traduit un désordre du contrôle physiologique de la ventilation.","src":"p. 107"},{"id":"p203-qroc-022","type":"QROC","rank":"A","objective":"p203-obj-03","tags":["clinique"],"difficulty":2,"question":"Quel signe correspond à un asynchronisme thoraco-abdominal chronique, témoin d'une dysfonction diaphragmatique ?","answer":"La respiration abdominale paradoxale","accept":["respiration abdominale paradoxale","abdominale paradoxale","respiration paradoxale"],"keywords":["paradox"],"explanation":"La respiration abdominale paradoxale et la mise en jeu inspiratoire des muscles du cou sont des signes physiques à rechercher ; l'antépnée est l'autre signe de dysfonction diaphragmatique.","src":"p. 108"},{"id":"p203-qroc-023","type":"QROC","rank":"A","objective":"p203-obj-03","tags":["clinique"],"difficulty":1,"question":"Quelles anomalies de percussion peut-on observer chez un patient dyspnéique ?","answer":"Une matité ou un tympanisme","accept":["matite ou tympanisme","matite et tympanisme","matite tympanisme","tympanisme matite"],"keywords":["matit","tympan"],"explanation":"À l'auscultation : crépitants, sibilants, râles bronchiques, abolition localisée du murmure vésiculaire ; à la palpation : augmentation ou réduction des vibrations vocales.","src":"p. 108"},{"id":"p203-qroc-024","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quel élément de l'examen constitue l'élément principal d'orientation étiologique d'une dyspnée chronique ?","answer":"L'auscultation pulmonaire","accept":["auscultation","auscultation pulmonaire"],"keywords":["auscultation"],"explanation":"L'interrogatoire permet d'émettre des hypothèses, mais c'est l'examen clinique, en particulier l'auscultation pulmonaire, qui oriente avant tout l'étiologie.","src":"p. 109"},{"id":"p203-qroc-025","type":"QROC","rank":"A","objective":"p203-obj-09","tags":["clinique","complications"],"difficulty":2,"question":"Quels sont les trois signes cliniques d'insuffisance respiratoire chronique ?","answer":"Hypertrophie des SCM, respiration à lèvres pincées, signe de Hoover","accept":["hypertrophie des sterno cleido mastoidiens levres pincees hoover","sterno cleido mastoidiens levres pincees hoover","scm levres pincees hoover","scm levres pincees signe de hoover"],"keywords":["levres","hoover"],"explanation":"Autres éléments d'orientation : anomalies pariétales (obésité, scoliose) et signes de dysfonction diaphragmatique (antépnée, respiration abdominale paradoxale).","src":"p. 108"},{"id":"p203-qroc-026","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["suivi","définition"],"difficulty":1,"question":"Quelle échelle est la plus utilisée pour quantifier la dyspnée chronique ?","answer":"L'échelle mMRC","accept":["mmrc","echelle mmrc","echelle modifiee du medical research council"],"keywords":["mmrc"],"explanation":"L'échelle modifiée du Medical Research Council évalue l'impact de la dyspnée sur des activités physiques classées en 5 catégories.","src":"p. 110-111"},{"id":"p203-qroc-027","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":1,"question":"Avec quelle échelle utilisée en cardiologie la cotation de la mMRC est-elle très proche ?","answer":"La NYHA (New York Heart Association)","accept":["nyha","new york heart association"],"keywords":["nyha"],"explanation":"Comme la NYHA en cardiologie, la mMRC catégorise l'impact de la dyspnée.","src":"p. 111"},{"id":"p203-qroc-028","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["suivi","pièges"],"difficulty":2,"question":"Quelle est la principale limite de l'échelle mMRC pour le suivi d'un patient ?","answer":"Elle est peu sensible au changement","accept":["peu sensible au changement","peu sensible","peu sensible aux changements"],"keywords":["peu sensible"],"explanation":"Elle sert donc mal à repérer une aggravation ou une amélioration ; on la complète par le score DIRECT en 10 questions.","src":"p. 111"},{"id":"p203-qroc-029","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":1,"question":"Quel stade de la mMRC correspond à un essoufflement trop important pour sortir de chez soi, ou apparaissant dès l'habillage ?","answer":"Le stade 4","accept":["stade 4","4"],"keywords":["4"],"explanation":"Le stade 3 est celui du patient qui doit faire une pause pour respirer après 90 mètres ou quelques minutes de marche à plat.","src":"p. 111"},{"id":"p203-qroc-030","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":1,"question":"Quel stade de la mMRC correspond à un arrêt pour reprendre son souffle après 90 mètres de marche ou après quelques minutes sur terrain plat ?","answer":"Le stade 3","accept":["stade 3","3"],"keywords":["3"],"explanation":"Le stade 4 correspond à un essoufflement trop important pour quitter la maison ou rien qu'à l'habillage.","src":"p. 111"},{"id":"p203-qroc-031","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":2,"question":"Quel stade de la mMRC correspond à une marche plus lente que celle des gens du même âge à plat, ou à un arrêt à son propre rythme de marche sur terrain plat ?","answer":"Le stade 2","accept":["stade 2","2"],"keywords":["2"],"explanation":"Le stade 1 correspond à un essoufflement en se dépêchant à plat ou en montant une pente légère ; le stade 0 à un essoufflement pour un effort important seulement.","src":"p. 111"},{"id":"p203-qroc-032","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":1,"question":"Quel score en 10 questions complète utilement l'échelle mMRC ?","answer":"Le score DIRECT","accept":["direct","score direct"],"keywords":["direct"],"explanation":"Le score DIRECT mesure le retentissement de la dyspnée sur la vie quotidienne.","src":"p. 111-112"},{"id":"p203-qroc-033","type":"QROC","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":1,"question":"Quel questionnaire est le plus répandu pour évaluer la qualité de vie liée à la santé respiratoire ?","answer":"Le CAT","accept":["cat","questionnaire cat"],"keywords":["cat"],"explanation":"La chronicité de la dyspnée, quelle qu'en soit la cause, altère la qualité de vie ; on y associe le questionnaire d'anxiété-dépression.","src":"p. 112"},{"id":"p203-qroc-034","type":"QROC","rank":"A","objective":"p203-obj-11","tags":["biologie","paraclinique"],"difficulty":1,"question":"Quel examen biologique de première intention permet d'éliminer une anémie devant une dyspnée chronique ?","answer":"La NFS","accept":["nfs","numeration formule sanguine","hemogramme"],"keywords":["nfs"],"explanation":"Les examens de première intention sont orientés par l'interrogatoire : radiographie thoracique, NFS, BNP si suspicion de cardiopathie, ECG.","src":"p. 109"},{"id":"p203-qroc-035","type":"QROC","rank":"A","objective":"p203-obj-11","tags":["biologie","paraclinique"],"difficulty":1,"question":"Quel dosage demande-t-on en première intention en cas de suspicion de cardiopathie ?","answer":"Le BNP","accept":["bnp","peptide natriuretique"],"keywords":["bnp"],"explanation":"L'ECG complète le bilan à la recherche de signes de cardiopathie dysrythmique ou ischémique.","src":"p. 109"},{"id":"p203-qroc-036","type":"QROC","rank":"A","objective":"p203-obj-11","tags":["ECG","paraclinique"],"difficulty":1,"question":"Quel examen de première intention cherche des signes de cardiopathie dysrythmique ou ischémique devant une dyspnée chronique ?","answer":"L'ECG","accept":["ecg","electrocardiogramme"],"keywords":["ecg"],"explanation":"Le BNP est demandé en cas de suspicion de cardiopathie, et une échographie cardiaque avec avis cardiologique est indiquée en cas d'orientation vers une cardiopathie.","src":"p. 109-110"},{"id":"p203-qroc-037","type":"QROC","rank":"A","objective":"p203-obj-13","tags":["imagerie","paraclinique"],"difficulty":2,"question":"Quels trois éléments cherche-t-on sur la radiographie thoracique d'orientation étiologique devant une dyspnée chronique ?","answer":"Distension, syndrome interstitiel, cardiomégalie","accept":["distension syndrome interstitiel cardiomegalie","distension interstitiel cardiomegalie","distension cardiomegalie syndrome interstitiel"],"keywords":["distension","interstiti","cardiomegal"],"explanation":"La radiographie thoracique est l'examen d'imagerie de première intention devant une dyspnée chronique.","src":"p. 109"},{"id":"p203-qroc-038","type":"QROC","rank":"A","objective":"p203-obj-12","tags":["paraclinique"],"difficulty":2,"question":"Quels trois éléments comprennent les explorations fonctionnelles respiratoires de repos devant une dyspnée d'orientation respiratoire ?","answer":"Spirométrie lente et forcée, pléthysmographie, DLCO","accept":["spirometrie plethysmographie dlco","spirometrie volumes statiques dlco","spirometrie plethysmographie et dlco"],"keywords":["spirom","plethysm","dlco"],"explanation":"La spirométrie comprend la courbe débit-volume ; la pléthysmographie détermine les volumes pulmonaires statiques ; on y associe la mesure de la DLCO.","src":"p. 109"},{"id":"p203-qroc-039","type":"QROC","rank":"A","objective":"p203-obj-12","tags":["paraclinique","biologie"],"difficulty":2,"question":"Pourquoi réalise-t-on une gazométrie artérielle de repos, en position assise, devant une dyspnée chronique d'orientation respiratoire ?","answer":"Rechercher une hypoxémie ou une hypoventilation alvéolaire chronique","accept":["hypoxemie","hypoventilation alveolaire","hypoxemie ou hypoventilation alveolaire chronique"],"keywords":["hypox","hypoventil"],"explanation":"C'est un examen de seconde intention, orienté par les examens de première intention et par la suspicion clinique.","src":"p. 110"},{"id":"p203-qroc-040","type":"QROC","rank":"A","objective":"p203-obj-12","tags":["paraclinique"],"difficulty":2,"question":"Citez un test simple permettant de détecter une désaturation d'exercice.","answer":"Test de marche de 6 minutes (ou lever de chaise de 3 minutes)","accept":["test de marche de 6 minutes","test de marche de 6 min","tm6","test de lever de chaise","lever de chaise de 3 minutes"],"keywords":["marche"],"explanation":"L'exploration idéale est l'exploration fonctionnelle d'exercice incrémentale sur cycloergomètre ; plus simplement, toute modalité d'exercice assez longue et standardisée convient pour détecter la désaturation.","src":"p. 110"},{"id":"p203-qroc-041","type":"QROC","rank":"A","objective":"p203-obj-12","tags":["paraclinique"],"difficulty":2,"question":"Quelle baisse de la SpO2 à l'exercice est considérée comme significative ?","answer":"3 %","accept":["3","delta 3","3 points"],"keywords":["3"],"explanation":"Une baisse de 3 % de la SpO2 lors d'un test de marche de 6 minutes ou d'un lever de chaise de 3 minutes témoigne d'une désaturation d'exercice.","src":"p. 110"},{"id":"p203-qroc-042","type":"QROC","rank":"A","objective":"p203-obj-12","tags":["paraclinique"],"difficulty":1,"question":"Que demande-t-on si l'orientation se fait vers une cardiopathie ?","answer":"Un avis cardiologique avec échographie cardiaque","accept":["avis cardiologique","echographie cardiaque","avis cardiologique et echographie cardiaque","echocardiographie"],"keywords":["cardiolog","echo"],"explanation":"Le choix des examens de seconde intention dépend des résultats de ceux de première intention et de la suspicion clinique.","src":"p. 110"},{"id":"p203-qroc-043","type":"QROC","rank":"A","objective":"p203-obj-13","tags":["imagerie"],"difficulty":2,"question":"Quelle orientation clinique justifie un scanner thoracique sans injection ?","answer":"Bronchopathie chronique ou pathologie interstitielle chronique","accept":["bronchopathie chronique ou pathologie interstitielle chronique","bronchopathie chronique et pathologie interstitielle chronique","bronchopathie ou pathologie interstitielle"],"keywords":["bronchopath","interstiti"],"explanation":"Avec injection, le scanner est réservé à l'orientation vers une cause vasculaire.","src":"p. 110"},{"id":"p203-qroc-044","type":"QROC","rank":"A","objective":"p203-obj-13","tags":["imagerie"],"difficulty":2,"question":"Pour quelles causes vasculaires demande-t-on un scanner thoracique injecté ?","answer":"Embolie pulmonaire, HTP, shunt droit-gauche","accept":["embolie pulmonaire hypertension pulmonaire shunt droit gauche","ep htp shunt droit gauche","ep htp shunt d g","embolie pulmonaire htp shunt droit gauche"],"keywords":["embolie","htp","shunt"],"explanation":"En cas d'orientation vers une bronchopathie chronique ou une pathologie interstitielle chronique, le scanner se fait sans injection.","src":"p. 110"},{"id":"p203-qru-101","type":"QRU","rank":"A","objective":"p203-obj-01","tags":["définition"],"difficulty":1,"stem":"Quelle proposition définit correctement la dyspnée ?","options":[{"t":"Une perception de respiration inconfortable ou pénible","ok":true,"why":"C'est une sensation de respiration inconfortable ou pénible, ressentie au repos ou à l'exercice dans des situations qui n'entraînent habituellement aucune gêne."},{"t":"Toute augmentation de la fréquence respiratoire (tachypnée)","ok":false,"why":"Faux : la dyspnée n'est pas une simple modification du rythme respiratoire ; on peut être tachypnéique sans être dyspnéique, et inversement."},{"t":"Une baisse de la saturation en oxygène mesurée à l'oxymètre","ok":false,"why":"Faux : la dyspnée est une sensation (une perception), pas une mesure."},{"t":"Une diminution de l'amplitude du volume courant (hypopnée)","ok":false,"why":"Faux : l'hypopnée est un terme descriptif du volume courant, pas la dyspnée."},{"t":"Une douleur thoracique survenant à l'effort","ok":false,"why":"Faux : la dyspnée est comparable à la douleur par ses deux composantes, mais ce n'est pas une douleur."}],"explanation":"La dyspnée associe une composante sensorielle (oppression thoracique, inspiration incomplète) et une composante affective (désagrément, anxiété, frayeur).","src":"p. 105"},{"id":"p203-qru-102","type":"QRU","rank":"A","objective":"p203-obj-07","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Un patient décrit une dyspnée inspiratoire bruyante, avec un cornage. Quelle atteinte faut-il rechercher en premier ?","options":[{"t":"Une obstruction des voies aériennes supérieures","ok":true,"why":"Une dyspnée inspiratoire avec cornage évoque une pathologie des voies aériennes supérieures (larynx et trachée extra-thoracique)."},{"t":"Une pathologie des bronches, comme dans l'asthme","ok":false,"why":"Faux : ce sont les sibilants expiratoires qui évoquent une pathologie des bronches."},{"t":"Une insuffisance cardiaque gauche décompensée","ok":false,"why":"Faux : l'insuffisance cardiaque se manifeste plutôt par une orthopnée."},{"t":"Une dysfonction diaphragmatique avec antépnée","ok":false,"why":"Faux : une dysfonction diaphragmatique se manifeste par une orthopnée ou une antépnée, non par un cornage."},{"t":"Un shunt anatomique intracardiaque ou intrapulmonaire","ok":false,"why":"Faux : un shunt évoque une platypnée."}],"explanation":"Stridor ou cornage = bruits inspiratoires ; sibilants ou sifflements = bruits expiratoires. Toute dyspnée avec bruits inspiratoires impose la recherche d'une obstruction des voies aériennes supérieures.","src":"p. 104, 107-108"},{"id":"p203-qru-103","type":"QRU","rank":"A","objective":"p203-obj-06","tags":["étiologie","clinique"],"difficulty":1,"stem":"Un patient se plaint d'une dyspnée en décubitus dorsal. Quelle est la première hypothèse ?","options":[{"t":"Une insuffisance cardiaque","ok":true,"why":"L'orthopnée évoque en premier une insuffisance cardiaque, une atteinte diaphragmatique restant possible."},{"t":"Un syndrome d'hyperventilation","ok":false,"why":"Faux : on l'évoque devant une dyspnée inexpliquée."},{"t":"Un shunt anatomique intracardiaque","ok":false,"why":"Faux : un shunt évoque une platypnée (dyspnée en position debout)."},{"t":"Une obstruction des voies aériennes supérieures","ok":false,"why":"Faux : elle se manifeste par des bruits inspiratoires (cornage)."},{"t":"Une pathologie des bronches avec sibilants expiratoires","ok":false,"why":"Faux : elle se manifeste par une dyspnée sifflante, non par une orthopnée."}],"explanation":"Orthopnée = dyspnée en décubitus dorsal : insuffisance cardiaque en première hypothèse, mais aussi dysfonction diaphragmatique ou obésité.","src":"p. 104, 107"},{"id":"p203-qru-104","type":"QRU","rank":"A","objective":"p203-obj-07","tags":["étiologie","clinique"],"difficulty":2,"stem":"Un patient présente une dyspnée survenant en position debout. Quelle étiologie faut-il évoquer ?","options":[{"t":"Un shunt intracardiaque ou intrapulmonaire","ok":true,"why":"La platypnée évoque un shunt : foramen ovale perméable, malformation ou fistule artério-veineuse, syndrome hépato-pulmonaire."},{"t":"Une insuffisance cardiaque gauche, avec orthopnée","ok":false,"why":"Faux : l'insuffisance cardiaque donne plutôt une dyspnée en décubitus dorsal."},{"t":"Une dysfonction diaphragmatique, avec antépnée","ok":false,"why":"Faux : elle donne une orthopnée ou une antépnée (dyspnée penché en avant)."},{"t":"Un asthme à prédominance nocturne, avec sibilants","ok":false,"why":"Faux : l'asthme est évoqué devant une dyspnée sifflante ou nocturne."},{"t":"Une obstruction des voies aériennes supérieures","ok":false,"why":"Faux : elle donne une dyspnée inspiratoire avec cornage."}],"explanation":"Platypnée = dyspnée en position debout ; orthopnée = décubitus dorsal ; antépnée = penché en avant.","src":"p. 107"},{"id":"p203-qru-105","type":"QRU","rank":"A","objective":"p203-obj-12","tags":["paraclinique","biologie"],"difficulty":1,"stem":"Quel examen de seconde intention permet de rechercher une hypoxémie ou une hypoventilation alvéolaire chronique ?","options":[{"t":"La gazométrie artérielle de repos, en position assise","ok":true,"why":"Elle est réalisée en cas d'orientation vers une pathologie respiratoire pour rechercher une hypoxémie ou une hypoventilation alvéolaire chronique."},{"t":"La spirométrie lente et forcée avec courbe débit-volume","ok":false,"why":"Faux : la spirométrie lente et forcée fait partie des EFR de repos, examen distinct de la gazométrie artérielle."},{"t":"La mesure de la DLCO, en plus de la spirométrie","ok":false,"why":"Faux : elle fait partie des EFR de repos, pas de la gazométrie."},{"t":"La pléthysmographie, qui détermine les volumes statiques","ok":false,"why":"Faux : elle détermine les volumes pulmonaires statiques."},{"t":"Le test de marche de 6 minutes, qui détecte une désaturation","ok":false,"why":"Faux : il détecte une désaturation d'exercice, non une hypoxémie ou une hypoventilation de repos."}],"explanation":"En cas d'orientation respiratoire : EFR de repos (spirométrie, pléthysmographie, DLCO), gazométrie artérielle de repos en position assise, explorations d'exercice, scanner thoracique.","src":"p. 109-110"},{"id":"p203-qru-106","type":"QRU","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":1,"stem":"Pour suivre l'impact d'une dyspnée chronique sur les activités physiques d'un patient, quelle échelle est la plus utilisée ?","options":[{"t":"L'échelle mMRC (Medical Research Council modifiée)","ok":true,"why":"C'est l'échelle la plus utilisée pour la dyspnée chronique ; elle évalue l'impact de la dyspnée sur des activités physiques."},{"t":"L'échelle NYHA, utilisée surtout en cardiologie","ok":false,"why":"Faux : la NYHA est utilisée en cardiologie et sa cotation est très proche de celle de la mMRC."},{"t":"Le questionnaire CAT, évaluant la qualité de vie respiratoire","ok":false,"why":"Faux : le CAT est le questionnaire de qualité de vie liée à la santé respiratoire le plus répandu."},{"t":"Le questionnaire d'anxiété-dépression, évaluant le retentissement","ok":false,"why":"Faux : il mesure le retentissement psychologique, non l'intensité de la dyspnée."},{"t":"Le score DIRECT, questionnaire en 10 questions","ok":false,"why":"Faux : le score DIRECT complète utilement la mMRC, il n'est pas l'échelle la plus utilisée."}],"explanation":"La mMRC classe l'impact de la dyspnée en 5 catégories mais est peu sensible au changement ; elle est complétée par le score DIRECT.","src":"p. 110-111"},{"id":"p203-qru-107","type":"QRU","rank":"A","objective":"p203-obj-13","tags":["imagerie"],"difficulty":2,"stem":"Devant une dyspnée chronique orientée vers une pathologie interstitielle chronique, comment réalise-t-on le scanner thoracique ?","options":[{"t":"Sans injection de produit de contraste","ok":true,"why":"Le scanner est réalisé sans injection en cas d'orientation vers une bronchopathie chronique ou une pathologie interstitielle chronique."},{"t":"Avec injection, comme devant toute dyspnée chronique","ok":false,"why":"Faux : l'injection est réservée à l'orientation vers une cause vasculaire (EP, HTP, shunt droit-gauche)."},{"t":"Avec injection, afin de rechercher une embolie pulmonaire","ok":false,"why":"Faux : l'injection s'adresse à une orientation vasculaire, ce qui n'est pas le cas ici."},{"t":"Sans injection, uniquement en cas de cause vasculaire","ok":false,"why":"Faux : une cause vasculaire justifie au contraire une injection."},{"t":"Il n'est pas indiqué, la radiographie suffit toujours","ok":false,"why":"Faux : le scanner est un examen de seconde intention dans l'orientation vers une pathologie interstitielle ou bronchique."}],"explanation":"Sans injection : bronchopathie chronique ou pathologie interstitielle chronique. Avec injection : cause vasculaire (embolie pulmonaire, hypertension pulmonaire, shunt droit-gauche).","src":"p. 110"},{"id":"p203-qcm-101","type":"QRM","rank":"A","objective":"p203-obj-01","tags":["définition"],"difficulty":1,"stem":"Concernant la définition de la dyspnée, quelles propositions sont exactes ?","options":[{"t":"Elle comporte une composante sensorielle et une composante affective et émotionnelle","ok":true,"why":"Comme la douleur : oppression thoracique ou inspiration incomplète d'une part, désagrément, anxiété ou frayeur d'autre part."},{"t":"On peut être tachypnéique sans être dyspnéique","ok":true,"why":"La dyspnée n'est pas simplement une modification du rythme respiratoire."},{"t":"Elle se résume à une accélération de la fréquence respiratoire","ok":false,"why":"Faux : on peut aussi être dyspnéique sans être tachypnéique."},{"t":"Elle ne se ressent que lors d'un effort important","ok":false,"why":"Faux : elle peut être ressentie au repos comme à l'exercice."},{"t":"Elle est exprimée de la même façon par tous les patients, quelle que soit leur culture","ok":false,"why":"Faux : elle s'exprime de façon très variable, notamment selon l'origine culturelle."}],"explanation":"Perception d'une respiration inconfortable ou pénible, avec une composante sensorielle et une composante affective ; le terme vient du grec (dys = difficulté, pnée = respirer).","src":"p. 104-105"},{"id":"p203-qcm-102","type":"QRM","rank":"A","objective":"p203-obj-01","tags":["physiopathologie"],"difficulty":2,"stem":"Concernant les mécanismes de la dyspnée, quelles propositions sont exactes ?","options":[{"t":"Elle résulte d'une inadéquation entre la demande ventilatoire et l'efficience du système respiratoire","ok":true,"why":"C'est le déséquilibre entre la commande centrale et la capacité du système respiratoire à y répondre."},{"t":"Le désordre peut venir de la commande, de l'effecteur ou, souvent, des deux","ok":true,"why":"Il peut s'agir d'un trouble de la commande, de l'effecteur ou des deux à la fois."},{"t":"La commande respiratoire est à la fois automatique (tronc cérébral) et volontaire (cortex moteur)","ok":true,"why":"Elle active d'abord les muscles dilatateurs du pharynx, puis les muscles inspiratoires, dont le diaphragme."},{"t":"La ventilation normale est un acte inconfortable, générant un désagrément modéré","ok":false,"why":"Faux : la ventilation normale est un acte confortable (« félicité respiratoire »), qui ne génère aucun désagrément."},{"t":"Le gaz carbonique est rejeté du sang vers l'alvéole lors de l'inspiration","ok":false,"why":"Faux : le gaz carbonique est transféré du sang au gaz alvéolaire et rejeté lors de l'expiration."}],"explanation":"La dyspnée est la conséquence d'un déséquilibre entre la demande ventilatoire (commande centrale) et l'efficience du système respiratoire.","src":"p. 105-106"},{"id":"p203-qcm-103","type":"QRM","rank":"A","objective":"p203-obj-01","tags":["définition"],"difficulty":1,"stem":"Quelle(s) association(s) terme-définition est (sont) exacte(s) ?","options":[{"t":"Hyperpnée : augmentation de l'amplitude du volume courant","ok":true,"why":"L'hyperpnée est l'augmentation de l'amplitude du volume courant."},{"t":"Hypopnée : augmentation de l'amplitude du volume courant","ok":false,"why":"Faux : l'hypopnée est la diminution de l'amplitude du volume courant."},{"t":"Bradypnée : augmentation excessive de la fréquence respiratoire","ok":false,"why":"Faux : la bradypnée est la réduction franche de la fréquence respiratoire."},{"t":"Tachypnée : réduction franche de la fréquence respiratoire","ok":false,"why":"Faux : la tachypnée (ou polypnée) est l'augmentation excessive de la fréquence respiratoire."},{"t":"Polypnée : diminution de l'amplitude du volume courant","ok":false,"why":"Faux : polypnée est synonyme de tachypnée."}],"explanation":"Volume courant : hyperpnée (amplitude augmentée), hypopnée (amplitude diminuée). Fréquence respiratoire : tachypnée ou polypnée (augmentation excessive), bradypnée (réduction franche).","src":"p. 107"},{"id":"p203-qcm-104","type":"QRM","rank":"A","objective":"p203-obj-07","tags":["clinique","définition"],"difficulty":1,"stem":"Quelles associations entre terme et circonstance de survenue sont exactes ?","options":[{"t":"Orthopnée : dyspnée en décubitus dorsal","ok":true,"why":"L'orthopnée survient allongé sur le dos."},{"t":"Antépnée : dyspnée en antéflexion (penché en avant)","ok":true,"why":"L'antépnée survient en position penchée en avant."},{"t":"Platypnée : dyspnée en position debout","ok":true,"why":"La platypnée survient en position debout."},{"t":"Orthopnée : dyspnée en position debout","ok":false,"why":"Faux : c'est la définition de la platypnée."},{"t":"Platypnée : dyspnée en décubitus dorsal","ok":false,"why":"Faux : c'est la définition de l'orthopnée."}],"explanation":"Orthopnée : couché ; antépnée : penché en avant ; platypnée : debout. Chacune oriente vers des étiologies différentes.","src":"p. 107"},{"id":"p203-qcm-105","type":"QRM","rank":"A","objective":"p203-obj-07","tags":["étiologie","clinique"],"difficulty":2,"stem":"Un patient se plaint d'une dyspnée apparaissant allongé sur le dos. Parmi ces étiologies, lesquelles sont à évoquer ?","options":[{"t":"Une insuffisance cardiaque","ok":true,"why":"C'est la première hypothèse."},{"t":"Une dysfonction diaphragmatique","ok":true,"why":"Une atteinte diaphragmatique est possible."},{"t":"Une obésité","ok":true,"why":"Elle est citée avec l'insuffisance cardiaque et la dysfonction diaphragmatique."},{"t":"Un shunt anatomique intracardiaque","ok":false,"why":"Faux : un shunt évoque une platypnée (dyspnée en position debout)."},{"t":"Une obstruction laryngée avec cornage","ok":false,"why":"Faux : elle donne une dyspnée inspiratoire avec cornage, sans lien avec la position."}],"explanation":"Orthopnée : insuffisance cardiaque, dysfonction diaphragmatique, obésité. Antépnée : dysfonction diaphragmatique, obésité. Platypnée : shunt.","src":"p. 104, 107"},{"id":"p203-qcm-106","type":"QRM","rank":"A","objective":"p203-obj-06","tags":["étiologie","clinique"],"difficulty":1,"stem":"Une dyspnée nocturne évoque avant tout :","options":[{"t":"Un œdème aigu pulmonaire","ok":true,"why":"C'est l'un des deux diagnostics évoqués avant tout devant une dyspnée nocturne."},{"t":"Un asthme","ok":true,"why":"C'est l'autre diagnostic évoqué avant tout."},{"t":"Un syndrome d'hyperventilation","ok":false,"why":"Faux : on l'évoque devant une dyspnée inexpliquée."},{"t":"Une obstruction des voies aériennes supérieures","ok":false,"why":"Faux : elle se manifeste par une dyspnée inspiratoire avec cornage."},{"t":"Un shunt intracardiaque (foramen ovale perméable)","ok":false,"why":"Faux : un shunt évoque une platypnée."}],"explanation":"La dyspnée peut être diurne, nocturne ou sans horaire ; la dyspnée nocturne évoque avant tout un œdème aigu pulmonaire ou un asthme.","src":"p. 107"},{"id":"p203-qcm-107","type":"QRM","rank":"A","objective":"p203-obj-06","tags":["étiologie","clinique"],"difficulty":2,"stem":"Chez un sujet âgé présentant une dyspnée sifflante, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"L'asthme est évoqué avant tout, mais aussi la BPCO et le cœur gauche (pseudo-asthme cardiaque)","ok":true,"why":"Chez le sujet âgé, la dyspnée sifflante peut être d'origine bronchique ou cardiaque gauche."},{"t":"Les sibilants sont des bruits inspiratoires qui évoquent d'abord une obstruction laryngée chez le sujet âgé","ok":false,"why":"Faux : les sibilants sont des bruits expiratoires ; les bruits inspiratoires (cornage) évoquent une atteinte des voies aériennes supérieures."},{"t":"Une cause cardiaque gauche est exclue dès lors que la dyspnée est sifflante, car elle ne donne jamais de sibilants","ok":false,"why":"Faux : le pseudo-asthme cardiaque est justement une dyspnée sifflante d'origine cardiaque gauche."},{"t":"Le syndrome d'hyperventilation est la première hypothèse à évoquer devant une dyspnée sifflante","ok":false,"why":"Faux : on l'évoque devant une dyspnée inexpliquée, pas devant une dyspnée sifflante."},{"t":"Il s'agit d'un cornage, qui évoque une atteinte des bronches plutôt que des voies aériennes supérieures","ok":false,"why":"Faux : le cornage est un bruit inspiratoire et évoque une atteinte des voies aériennes supérieures."}],"explanation":"Devant une dyspnée sifflante du sujet âgé : asthme d'abord, mais aussi BPCO et cœur gauche.","trap":"Une dyspnée sifflante du sujet âgé n'est pas toujours un asthme.","src":"p. 104, 107"},{"id":"p203-qcm-108","type":"QRM","rank":"A","objective":"p203-obj-02","tags":["diagnostic"],"difficulty":2,"stem":"Parmi les six questions clés devant une dyspnée, lesquelles figurent dans la démarche ?","options":[{"t":"Est-elle aiguë ou chronique ?","ok":true,"why":"C'est la première question à se poser."},{"t":"Chez qui : quels sont le terrain, les antécédents et les traitements usuels ?","ok":true,"why":"Âge, tabagisme, allergie, antécédents pneumologiques, cardio-vasculaires, neuro-psychiatriques."},{"t":"Avec quels signes extra-respiratoires ?","ok":true,"why":"Atteinte pariétale thoracique, neuromusculaire, rhumatologique, anomalies cardiaques."},{"t":"Quelle est la valeur du BNP à l'arrivée du patient ?","ok":false,"why":"Faux : il s'agit d'un examen complémentaire, pas d'une des six questions clés de l'orientation."},{"t":"Quel est le résultat de la DLCO en exploration fonctionnelle ?","ok":false,"why":"Faux : il s'agit d'un examen de seconde intention, pas d'une des six questions clés."}],"explanation":"Six questions dans l'ordre : aiguë ou chronique ? chez qui ? facteurs favorisants ? quand (rythmicité) ? comment (circonstances) ? quels signes respiratoires associés, et quels signes extra-respiratoires ?","src":"p. 104"},{"id":"p203-qcm-109","type":"QRM","rank":"B","objective":"p203-obj-08","tags":["physiopathologie","définition"],"difficulty":2,"stem":"Concernant l'hyperventilation excessive (HVE) et le dysfunctional breathing, quelles propositions sont exactes ?","options":[{"t":"L'HVE est une réponse ventilatoire supérieure aux besoins physiologiques","ok":true,"why":"C'est la définition de l'hyperventilation excessive au sens strict."},{"t":"Dans l'HVE, la hausse de la fréquence et celle du volume courant sont harmonieuses","ok":true,"why":"Dans l'HVE, la fréquence respiratoire et le volume courant montent ensemble, de façon harmonieuse."},{"t":"Le dysfunctional breathing associe une hausse non harmonieuse de la fréquence et du volume courant","ok":true,"why":"Il correspond à un désordre du contrôle physiologique de la ventilation."},{"t":"Le dysfunctional breathing correspond à une hausse harmonieuse de la fréquence et du volume courant","ok":false,"why":"Faux : c'est précisément la non-harmonie entre fréquence et volume courant qui le définit."},{"t":"L'hyperventilation est la première hypothèse à évoquer devant toute dyspnée aiguë","ok":false,"why":"Faux : une dyspnée aiguë est une urgence jusqu'à preuve du contraire ; l'hyperventilation se discute devant une dyspnée inexpliquée."}],"explanation":"Pour apprécier une hyperventilation, on observe ou mesure à la fois le volume courant et la fréquence respiratoire.","src":"p. 104, 107"},{"id":"p203-qcm-110","type":"QRM","rank":"A","objective":"p203-obj-03","tags":["clinique"],"difficulty":2,"stem":"Quels éléments de l'examen physique sont à rechercher devant une dyspnée ?","options":[{"t":"Des anomalies auscultatoires (crépitants, sibilants, râles, abolition du murmure)","ok":true,"why":"Crépitants, sibilants, râles bronchiques, abolition localisée du murmure vésiculaire."},{"t":"Des anomalies de percussion : matité ou tympanisme","ok":true,"why":"Ce sont les deux anomalies de percussion décrites."},{"t":"Une mise en jeu inspiratoire des muscles du cou ou une respiration abdominale paradoxale","ok":true,"why":"Ces deux signes figurent parmi les signes physiques à rechercher (++)."},{"t":"Une augmentation exclusive des vibrations vocales, jamais leur réduction","ok":false,"why":"Faux : les vibrations vocales peuvent être augmentées ou réduites."},{"t":"Aucun signe d'insuffisance cardiaque, qui n'a pas sa place dans l'examen d'une dyspnée","ok":false,"why":"Faux : on recherche des signes d'insuffisance cardiaque gauche et droite."}],"explanation":"On recherche aussi des signes généraux (fièvre, altération de l'état général, sueurs) et des symptômes associés (douleur thoracique, palpitations, toux, expectorations).","src":"p. 108"},{"id":"p203-qcm-111","type":"QRM","rank":"A","objective":"p203-obj-09","tags":["clinique","complications"],"difficulty":2,"stem":"Lors de l'examen d'un patient dyspnéique chronique, quels éléments évoquent une insuffisance respiratoire chronique ?","options":[{"t":"Une hypertrophie des muscles sterno-cléido-mastoïdiens","ok":true,"why":"C'est l'un des trois signes d'insuffisance respiratoire chronique."},{"t":"Une respiration à lèvres pincées","ok":true,"why":"C'est le deuxième signe."},{"t":"Le signe de Hoover","ok":true,"why":"C'est le troisième signe."},{"t":"Une antépnée, signe de dysfonction diaphragmatique","ok":false,"why":"Faux : l'antépnée appartient aux signes de dysfonction diaphragmatique."},{"t":"Une scoliose, anomalie pariétale","ok":false,"why":"Faux : la scoliose est une anomalie pariétale, qui oriente l'étiologie sans être un signe d'insuffisance respiratoire chronique."}],"explanation":"Signes d'insuffisance respiratoire chronique : hypertrophie des SCM, respiration à lèvres pincées, signe de Hoover ; signes de dysfonction diaphragmatique : antépnée, asynchronisme thoraco-abdominal.","src":"p. 108"},{"id":"p203-qcm-112","type":"QRM","rank":"A","objective":"p203-obj-05","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Concernant l'orientation étiologique d'une dyspnée chronique, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"L'auscultation pulmonaire est l'élément principal d'orientation étiologique","ok":true,"why":"L'interrogatoire permet d'émettre des hypothèses, l'examen clinique et en particulier l'auscultation oriente l'étiologie."},{"t":"L'interrogatoire est inutile, l'orientation reposant uniquement sur les examens complémentaires","ok":false,"why":"Faux : la sémiologie repose d'abord et principalement sur l'interrogatoire, et les examens complémentaires sont orientés par lui."},{"t":"Le BNP est le premier élément d'orientation, avant l'examen clinique","ok":false,"why":"Faux : le BNP n'est demandé qu'en cas de suspicion de cardiopathie."},{"t":"La gazométrie artérielle de repos est l'élément principal d'orientation","ok":false,"why":"Faux : c'est un examen de seconde intention."},{"t":"Les antécédents et les circonstances de survenue n'ont aucun intérêt pour l'orientation","ok":false,"why":"Faux : le contexte (âge, tabagisme, allergie) et les circonstances (horaire, position, facteurs déclenchants) orientent l'étiologie."}],"explanation":"L'orientation dépend du contexte, des circonstances de survenue et des signes cliniques associés ; l'auscultation pulmonaire est l'élément principal.","src":"p. 108-109"},{"id":"p203-qcm-113","type":"QRM","rank":"A","objective":"p203-obj-11","tags":["paraclinique","biologie","ECG"],"difficulty":2,"stem":"Quels examens sont de première intention devant une dyspnée chronique ?","options":[{"t":"Une radiographie thoracique d'orientation étiologique","ok":true,"why":"Elle recherche une distension, un syndrome interstitiel, une cardiomégalie."},{"t":"Une NFS, pour éliminer une anémie","ok":true,"why":"L'anémie est une cause à éliminer."},{"t":"Un BNP en cas de suspicion de cardiopathie","ok":true,"why":"Il est demandé si l'on suspecte une cardiopathie."},{"t":"Un ECG, à la recherche d'une cardiopathie dysrythmique ou ischémique","ok":true,"why":"Il complète le bilan de première intention."},{"t":"La mesure de la DLCO","ok":false,"why":"Faux : elle fait partie des EFR de repos, examens de seconde intention."}],"explanation":"Première intention : radiographie thoracique, NFS, BNP si suspicion de cardiopathie, ECG. Seconde intention : explorations orientées par ces examens et par la clinique.","src":"p. 109"},{"id":"p203-qcm-114","type":"QRM","rank":"A","objective":"p203-obj-12","tags":["paraclinique"],"difficulty":2,"stem":"Parmi les examens suivants, lesquels font partie des EFR de repos prescrites en seconde intention devant une dyspnée chronique d'orientation respiratoire ?","options":[{"t":"Une spirométrie lente et forcée (courbe débit-volume)","ok":true,"why":"C'est le premier élément des EFR de repos."},{"t":"La détermination des volumes pulmonaires statiques (pléthysmographie)","ok":true,"why":"C'est le deuxième élément."},{"t":"La mesure de la DLCO","ok":true,"why":"C'est le troisième élément."},{"t":"Un test de marche de 6 minutes","ok":false,"why":"Faux : c'est une exploration d'exercice."},{"t":"Une échographie cardiaque","ok":false,"why":"Faux : elle est indiquée en cas d'orientation vers une cardiopathie, avec un avis cardiologique."}],"explanation":"En cas d'orientation respiratoire : EFR de repos, gazométrie artérielle de repos, explorations d'exercice, scanner thoracique.","src":"p. 109-110"},{"id":"p203-qcm-115","type":"QRM","rank":"A","objective":"p203-obj-12","tags":["paraclinique"],"difficulty":2,"stem":"Pour détecter une désaturation d'exercice, quelles propositions sont exactes ?","options":[{"t":"Le test de marche de 6 minutes est une option simple","ok":true,"why":"Il permet de détecter une baisse significative de la SpO2."},{"t":"Le test de lever de chaise de 3 minutes est une option simple","ok":true,"why":"Toute modalité d'exercice assez longue et standardisée convient."},{"t":"Une baisse de la SpO2 de 3 % est significative","ok":true,"why":"Une baisse de 3 % (Δ 3 %) est le seuil de significativité cité."},{"t":"Seule une baisse de la SpO2 de 10 % est significative","ok":false,"why":"Faux : le seuil cité est de 3 %."},{"t":"La gazométrie artérielle de repos suffit à détecter une désaturation d'exercice","ok":false,"why":"Faux : elle recherche une hypoxémie ou une hypoventilation de repos ; l'exploration idéale est l'exercice incrémental sur cycloergomètre."}],"explanation":"L'idéal est l'épreuve d'effort incrémentale sur cycloergomètre ; plus simplement, le test de marche de 6 minutes ou le test de lever de chaise de 3 minutes suffit.","src":"p. 110"},{"id":"p203-qcm-116","type":"QRM","rank":"A","objective":"p203-obj-13","tags":["imagerie"],"difficulty":2,"stem":"Concernant le scanner thoracique devant une dyspnée chronique, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Il est injecté si l'on est orienté vers une cause vasculaire (EP, HTP, shunt D-G)","ok":true,"why":"L'injection est réservée à l'orientation vasculaire : embolie pulmonaire, hypertension pulmonaire, shunt droit-gauche."},{"t":"Il est réalisé sans injection quand on suspecte une embolie pulmonaire ou une HTP","ok":false,"why":"Faux : une orientation vers une embolie pulmonaire ou une HTP impose une injection."},{"t":"Il est systématiquement injecté, y compris en cas de bronchopathie chronique ou interstitielle","ok":false,"why":"Faux : en cas de bronchopathie chronique ou de pathologie interstitielle chronique, on le réalise sans injection."},{"t":"Il remplace la radiographie thoracique, qui n'est plus indiquée en première intention","ok":false,"why":"Faux : la radiographie thoracique d'orientation reste l'examen d'imagerie de première intention."},{"t":"Il est réalisé sans injection dans l'orientation vers un shunt droit-gauche","ok":false,"why":"Faux : le shunt droit-gauche fait partie des causes vasculaires justifiant une injection."}],"explanation":"Radiographie en première intention ; scanner en seconde intention, sans injection (bronchopathie ou pathologie interstitielle chronique) ou avec injection (cause vasculaire).","src":"p. 109-110"},{"id":"p203-qcm-117","type":"QRM","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":2,"stem":"Concernant l'échelle mMRC, quelles propositions sont exactes ?","options":[{"t":"C'est l'échelle la plus utilisée pour la dyspnée chronique","ok":true,"why":"Elle évalue l'impact de la dyspnée sur des activités physiques."},{"t":"Sa cotation est très proche de celle de la NYHA","ok":true,"why":"La NYHA est son équivalent en cardiologie."},{"t":"Elle est peu sensible au changement","ok":true,"why":"Elle sert donc mal à repérer une aggravation ou une amélioration."},{"t":"Elle est très sensible au changement, idéale pour juger d'une amélioration","ok":false,"why":"Faux : c'est l'inverse, d'où l'intérêt de la compléter par le score DIRECT."},{"t":"Elle ne s'utilise que pour la dyspnée aiguë","ok":false,"why":"Faux : c'est l'échelle de référence de la dyspnée chronique."}],"explanation":"La quantification de la dyspnée chronique sert au suivi, à l'évaluation des traitements et à la mesure de l'impact sur la qualité de vie, avec des auto-questionnaires courts et validés.","src":"p. 110-111"},{"id":"p203-qcm-118","type":"QRM","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":2,"stem":"Quelle(s) association(s) stade mMRC-description est (sont) exacte(s) ?","options":[{"t":"Stade 3 : pause pour respirer après 90 mètres de marche ou quelques minutes à plat","ok":true,"why":"C'est la description du stade 3."},{"t":"Stade 4 : essoufflement uniquement pour un effort important, sans autre gêne","ok":false,"why":"Faux : l'essoufflement pour un effort important seulement correspond au stade 0."},{"t":"Stade 0 : trop essoufflé pour quitter sa maison ou pour s'habiller seul","ok":false,"why":"Faux : c'est le stade 4."},{"t":"Stade 1 : essoufflé rien qu'à s'habiller, au repos comme à l'effort","ok":false,"why":"Faux : le stade 1 correspond à un essoufflement en se dépêchant à plat ou en montant une pente légère."},{"t":"Stade 2 : essoufflé seulement pour un effort important, comme les gens du même âge","ok":false,"why":"Faux : au stade 2, on marche moins vite que les gens de son âge à plat ou on doit s'arrêter à son rythme à plat."}],"explanation":"mMRC : 0 effort important ; 1 se dépêcher ou pente légère ; 2 marche plus lente que les gens du même âge ou arrêt à plat ; 3 arrêt après 90 mètres ou quelques minutes ; 4 trop essoufflé pour sortir ou pour s'habiller.","src":"p. 111"},{"id":"p203-qcm-119","type":"QRM","rank":"A","objective":"p203-obj-05","tags":["suivi"],"difficulty":2,"stem":"Concernant le retentissement de la dyspnée chronique, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Le CAT est le plus répandu pour la qualité de vie liée à la santé respiratoire","ok":true,"why":"Le questionnaire anxiété-dépression y est associé pour le retentissement psychologique."},{"t":"Le CAT évalue uniquement la fonction cardiaque du patient dyspnéique et pas sa qualité de vie","ok":false,"why":"Faux : le CAT évalue la qualité de vie liée à la santé respiratoire."},{"t":"L'impact sur la qualité de vie dépend de la cause et n'existe pas dans les causes bénignes","ok":false,"why":"Faux : une dyspnée chronique dégrade la qualité de vie quelle que soit sa cause, y compris bénigne."},{"t":"Le score DIRECT comporte une centaine de questions, ce qui en limite l'usage en pratique courante","ok":false,"why":"Faux : le score DIRECT comporte 10 questions."},{"t":"La NYHA est le questionnaire de qualité de vie le plus répandu en pneumologie","ok":false,"why":"Faux : la NYHA est une échelle d'impact de la dyspnée utilisée en cardiologie."}],"explanation":"La dyspnée chronique altère la qualité de vie quelle que soit sa cause ; les auto-questionnaires doivent être courts et validés.","src":"p. 111-112"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p203-pareto","points":[{"id":"p203-par-01","rank":"A","cat":"définition","text":"**Dyspnée** = perception d'une respiration **inconfortable ou pénible** (composantes **sensorielle** et **affective**) ; différente de la tachypnée : on peut être tachypnéique sans dyspnée, et inversement","src":"p. 105"},{"id":"p203-par-02","rank":"A","cat":"gravité","text":"**Dyspnée aiguë = URGENCE** jusqu'à preuve du contraire : apprécier d'emblée le **pronostic vital** ; installation **brutale** (quelques heures à quelques jours)","src":"p. 104, 106"},{"id":"p203-par-03","rank":"A","cat":"clinique","text":"**Cornage** (bruit inspiratoire) = atteinte des **voies aériennes supérieures** (larynx, trachée extra-thoracique) ; **sibilants** (bruits expiratoires) = atteinte des **bronches**","src":"p. 104, 107"},{"id":"p203-par-04","rank":"A","cat":"clinique","text":"**Orthopnée** (décubitus) : **insuffisance cardiaque** d'abord, puis dysfonction diaphragmatique, obésité ; **antépnée** : dysfonction diaphragmatique, obésité ; **platypnée** (debout) : **shunt**","src":"p. 104, 107"},{"id":"p203-par-05","rank":"A","cat":"clinique","text":"Dyspnée **nocturne** → **OAP** ou **asthme** ; dyspnée **sifflante** du sujet âgé → **asthme** d'abord, puis BPCO, ou **cœur gauche** (« pseudo-asthme cardiaque »)","src":"p. 104, 107"},{"id":"p203-par-06","rank":"A","cat":"piège","text":"Dyspnée **inexpliquée** → penser au syndrome d'**hyperventilation** (dysfunctional breathing : hausse non harmonieuse de la fréquence et du volume courant)","src":"p. 104, 107"},{"id":"p203-par-07","rank":"A","cat":"définition","text":"Dyspnée **chronique** = ≥ **8 semaines** ; **6 questions clés** : aiguë/chronique ? terrain ? facteurs favorisants ? rythmicité ? circonstances ? signes associés (respiratoires, extra-respiratoires)","src":"p. 104, 106"},{"id":"p203-par-08","rank":"A","cat":"examen","text":"**Auscultation pulmonaire** = élément principal d'orientation d'une dyspnée chronique ; autres signes : muscles du cou, respiration abdominale **paradoxale** ; IRC : SCM, **lèvres pincées**, **Hoover**","src":"p. 108-109"},{"id":"p203-par-09","rank":"A","cat":"examen","text":"1re intention : **radiographie thoracique** (distension, syndrome interstitiel, cardiomégalie), **NFS** (anémie), **BNP** si cardiopathie suspectée, **ECG** (cardiopathie dysrythmique ou ischémique)","src":"p. 109"},{"id":"p203-par-10","rank":"A","cat":"examen","text":"2e intention respiratoire : **EFR** de repos (spirométrie, pléthysmographie, **DLCO**), **gazométrie** artérielle de repos, tests d'exercice (**marche de 6 min**, lever de chaise 3 min ; baisse de **SpO2 de 3 %**)","src":"p. 109-110"},{"id":"p203-par-11","rank":"A","cat":"examen","text":"**Scanner** thoracique **sans injection** si bronchopathie ou pathologie interstitielle chronique ; **avec injection** si cause vasculaire (EP, HTP, shunt D-G) ; cardiopathie → avis cardiologique + écho","src":"p. 110"},{"id":"p203-par-12","rank":"A","cat":"suivi","text":"**mMRC** = échelle la plus utilisée (impact sur les activités, proche de la **NYHA**), peu sensible au changement ; la compléter par **DIRECT** ; qualité de vie : **CAT**","src":"p. 110-112"},{"id":"p203-par-13","rank":"A","cat":"chiffre","text":"Stades **mMRC** : 0 effort important ; 1 se dépêcher ou pente légère ; 2 marche **plus lente** que les gens de son âge ; 3 arrêt après **90 m** ; 4 trop essoufflé pour **sortir** ou s'habiller","src":"p. 111"},{"id":"p203-par-14","rank":"A","cat":"étiologie","text":"Facteurs à chercher : exposition **allergénique**, **sevrage** médicamenteux, infection, voyage **aérien**, chirurgie, iatrogénie ; en chronique : effort, froid, écart de régime **hyposodé**, arrêt du traitement de fond","src":"p. 104, 108"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
